import { useState, useRef, useEffect } from "react";

// ─── SYSTEM PROMPT ─────────────────────────────────────────────────────────────
const SYSTEM_PROMPT = `You are JK Assistant, the official AI chatbot for JK Physio / Gym / Rehab Centre. You are warm, motivating, and professional. You answer questions across four areas:

🏋️ GYM & FITNESS
- Equipment: Free weights (5-100kg), cable machines, smith machine, leg press, lat pulldown, chest press, rowing machines, treadmills, ellipticals, spin bikes, battle ropes, pull-up bars, resistance bands
- Classes: HIIT (Mon/Wed/Fri 7am & 6pm), Yoga (Tue/Thu 8am), Spinning (Mon/Wed/Fri 5:30pm), Zumba (Sat 10am), Strength & Conditioning (Tue/Thu 6pm)
- Personal Training: 8 sessions/month Rs.3200, 12 sessions/month Rs.4500
- Gym Hours: Mon-Sat 5:30am-10pm, Sun 7am-6pm
- Give workout splits, form tips, sets/reps guidance and progression advice

🦴 PHYSIOTHERAPY & REHAB
- Services: Post-surgical rehab, sports injury recovery, back & neck pain, posture correction, joint mobilization, dry needling, ultrasound therapy, TENS therapy, kinesio taping, hydrotherapy
- Conditions: ACL/knee injuries, shoulder impingement, frozen shoulder, herniated disc, sciatica, plantar fasciitis, tennis elbow, carpal tunnel, ankle sprains, post-fracture rehab
- Assessment: Initial Rs.800 (45 min), follow-up Rs.500 (30 min)
- 3 certified physiotherapists on staff; appointment required

🥗 DIET & NUTRITION
- Nutrition counseling: Rs.1200 for full diet plan
- Protein: 0.8-2g/kg body weight for muscle gain
- Pre-workout: Complex carbs + protein 60-90 min before (oats + banana, rice + chicken)
- Post-workout: Fast protein + carbs within 30-45 min (whey shake + fruit)
- Hydration: 2.5-4L water/day
- Supplements: Whey protein, creatine monohydrate, omega-3s, vitamin D3

💳 MEMBERSHIP & PRICING
- Monthly: Rs.1500 (gym), Rs.2200 (gym+classes), Rs.3500 (premium+physio x2)
- Quarterly: Rs.4000 / Rs.6000 / Rs.9000
- Annual: Rs.14000 / Rs.20000 / Rs.30000
- Student discount: 20% off with valid ID
- Couples plan: 15% off
- Free 1-day trial available
- Registration: Rs.500 one-time

RULES: Always refer to centre as "JK Physio / Gym / Rehab". For pain/injury symptoms, recommend seeing a JK physiotherapist. Be encouraging. If asked outside scope say: "I'm JK Assistant - I specialise in fitness, physiotherapy, nutrition, and membership. Happy to help with any of those!" Respond in same language as user (English or Hindi/Hinglish).`;

// ─── CONFIG ────────────────────────────────────────────────────────────────────
const HARDCODED_API_KEY = ""; // ← Paste your Gemini API key here: "AIzaSy..."

const QUICK_PROMPTS = [
  { label: "Beginner Workout Plan", icon: "🏋️" },
  { label: "Knee Rehab Exercises",  icon: "🦴" },
  { label: "Weight Loss Diet",      icon: "🥗" },
  { label: "Membership Plans",      icon: "💳" },
  { label: "Post-Workout Nutrition",icon: "🥤" },
  { label: "Back Pain Treatment",   icon: "💆" },
];

const RED      = "#C8102E";
const RED_DARK = "#9b0e23";

// ─── JK LOGO (SVG with React-safe attributes) ─────────────────────────────────
function JKLogo({ size = 38 }) {
  return (
    <svg width={size} height={size} viewBox="0 0 100 100" fill="none" xmlns="http://www.w3.org/2000/svg">
      <rect width="100" height="100" rx="10" fill="#C8102E" />
      <rect x="4" y="4" width="42" height="72" rx="3" fill="white" />
      <text
        x="25" y="62"
        textAnchor="middle"
        style={{ fontFamily: "Georgia, serif", fontWeight: "bold", fontSize: "52px" }}
        fill="#C8102E"
      >J</text>
      <text
        x="72" y="62"
        textAnchor="middle"
        style={{ fontFamily: "Georgia, serif", fontWeight: "bold", fontSize: "52px" }}
        fill="white"
      >K</text>
      <rect x="4" y="82" width="92" height="14" rx="3" fill="white" opacity="0.15" />
      <text
        x="50" y="93"
        textAnchor="middle"
        style={{ fontFamily: "Arial, sans-serif", fontWeight: "bold", fontSize: "9px", letterSpacing: "1px" }}
        fill="white"
      >PHYSIO / GYM / REHAB</text>
    </svg>
  );
}

// ─── TYPEWRITER ────────────────────────────────────────────────────────────────
function TypewriterText({ text, speed = 6, onDone }) {
  const [displayed, setDisplayed] = useState("");
  const idxRef = useRef(0);

  useEffect(() => {
    setDisplayed("");
    idxRef.current = 0;
    if (!text) return;
    const iv = setInterval(() => {
      if (idxRef.current < text.length) {
        setDisplayed(text.slice(0, ++idxRef.current));
      } else {
        clearInterval(iv);
        onDone && onDone();
      }
    }, speed);
    return () => clearInterval(iv);
  }, [text]); // eslint-disable-line

  return (
    <span style={{ whiteSpace: "pre-wrap" }}>
      {displayed}
      <span style={{ animation: "jkBlink 0.8s step-end infinite" }}>▋</span>
    </span>
  );
}

// ─── MARKDOWN RENDERER ─────────────────────────────────────────────────────────
function renderMd(text) {
  return text.split("\n").map((line, i) => {
    if (line.startsWith("## ")) {
      return <div key={i} style={{ fontWeight: 700, fontSize: "0.9rem", color: "#fff", margin: "0.75rem 0 0.2rem" }}>{line.slice(3)}</div>;
    }
    if (line.startsWith("### ")) {
      return <div key={i} style={{ fontWeight: 700, fontSize: "0.83rem", color: "#eee", margin: "0.6rem 0 0.15rem" }}>{line.slice(4)}</div>;
    }
    if (line.startsWith("- ") || line.startsWith("• ")) {
      return (
        <div key={i} style={{ display: "flex", gap: "0.4rem", marginBottom: "0.2rem" }}>
          <span style={{ color: RED, flexShrink: 0, fontWeight: "bold" }}>▸</span>
          <span>{renderInline(line.slice(2))}</span>
        </div>
      );
    }
    const numMatch = line.match(/^(\d+)\.\s(.+)/);
    if (numMatch) {
      return (
        <div key={i} style={{ display: "flex", gap: "0.4rem", marginBottom: "0.2rem" }}>
          <span style={{ color: RED, minWidth: "1.2rem", flexShrink: 0, fontWeight: 600 }}>{numMatch[1]}.</span>
          <span>{renderInline(numMatch[2])}</span>
        </div>
      );
    }
    if (!line.trim() || line.trim() === "---") return <div key={i} style={{ height: "0.3rem" }} />;
    return <div key={i} style={{ marginBottom: "0.1rem" }}>{renderInline(line)}</div>;
  });
}

function renderInline(text) {
  if (!text) return null;
  return text.split(/(\*\*[^*]+\*\*)/g).map((p, i) =>
    p.startsWith("**") && p.endsWith("**")
      ? <strong key={i} style={{ color: "#fff", fontWeight: 600 }}>{p.slice(2, -2)}</strong>
      : <span key={i}>{p}</span>
  );
}

// ─── MAIN COMPONENT ────────────────────────────────────────────────────────────
export default function JKChatbot() {
  const [open, setOpen]         = useState(false);
  const [messages, setMessages] = useState([
    {
      role: "assistant",
      text: "Welcome to **JK Physio / Gym / Rehab**! 💪\n\nI'm your JK Assistant — ask me anything about workouts, physiotherapy & rehab, diet plans, or membership.\n\nHow can I help you today?",
      done: true,
    },
  ]);
  const [input, setInput]       = useState("");
  const [apiKey, setApiKey]     = useState(HARDCODED_API_KEY);
  const [showKey, setShowKey]   = useState(false);
  const [loading, setLoading]   = useState(false);
  const [error, setError]       = useState("");
  const [unread, setUnread]     = useState(0);
  const [bounce, setBounce]     = useState(false);

  const bottomRef   = useRef(null);
  const textareaRef = useRef(null);

  // Scroll to bottom
  useEffect(() => {
    bottomRef.current && bottomRef.current.scrollIntoView({ behavior: "smooth" });
  }, [messages, loading]);

  // Bounce FAB after 4s
  useEffect(() => {
    const t = setTimeout(() => setBounce(true), 4000);
    return () => clearTimeout(t);
  }, []);

  // Unread badge
  useEffect(() => {
    if (!open && messages.length > 1) setUnread((n) => n + 1);
  }, [messages.length]); // eslint-disable-line

  const openChat  = () => { setOpen(true); setUnread(0); setBounce(false); };
  const closeChat = () => setOpen(false);

  const sendMessage = async (overrideText) => {
    const msg = (overrideText || input).trim();
    if (!msg) return;
    if (!apiKey.trim()) { setShowKey(true); setError("Please enter your Gemini API key to start chatting."); return; }

    setError("");
    setInput("");
    if (textareaRef.current) textareaRef.current.style.height = "auto";
    setMessages((prev) => [...prev, { role: "user", text: msg, done: true }]);
    setLoading(true);

    const history = messages.slice(1).map((m) => ({
      role: m.role === "assistant" ? "model" : "user",
      parts: [{ text: m.text }],
    }));

    try {
      const res = await fetch(
        `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=${apiKey.trim()}`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            system_instruction: { parts: [{ text: SYSTEM_PROMPT }] },
            contents: [...history, { role: "user", parts: [{ text: msg }] }],
            generationConfig: { temperature: 0.7, maxOutputTokens: 1024 },
          }),
        }
      );
      const data = await res.json();
      if (!res.ok) throw new Error(data.error?.message || "API error");
      const reply = data.candidates?.[0]?.content?.parts?.[0]?.text;
      if (!reply) throw new Error("No response received.");
      setMessages((prev) => [...prev, { role: "assistant", text: reply, done: false }]);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  // ─── STYLES ──────────────────────────────────────────────────────────────────
  const S = {
    fab: {
      position: "fixed", bottom: 28, right: 28,
      width: 62, height: 62,
      borderRadius: 18,
      background: `linear-gradient(135deg, ${RED}, ${RED_DARK})`,
      border: "none", cursor: "pointer", zIndex: 9998,
      display: "flex", alignItems: "center", justifyContent: "center",
      boxShadow: `0 8px 28px rgba(200,16,46,0.45), 0 2px 8px rgba(0,0,0,0.3)`,
      transition: "transform 0.2s, box-shadow 0.2s",
      animation: bounce ? "jkBounce 0.8s ease" : "none",
    },
    unread: {
      position: "absolute", top: -6, right: -6,
      background: "#fff", color: RED,
      fontSize: "0.62rem", fontWeight: 700,
      width: 20, height: 20, borderRadius: "50%",
      display: "flex", alignItems: "center", justifyContent: "center",
      border: `2px solid ${RED}`,
    },
    window: {
      position: "fixed", bottom: 102, right: 28,
      width: "min(420px, calc(100vw - 32px))",
      height: "min(620px, calc(100vh - 130px))",
      background: "#0f0f0f",
      borderRadius: 20,
      border: "1px solid rgba(200,16,46,0.25)",
      boxShadow: "0 24px 60px rgba(0,0,0,0.6)",
      display: "flex", flexDirection: "column",
      overflow: "hidden", zIndex: 9999,
      animation: "jkFadeUp 0.32s cubic-bezier(0.34,1.56,0.64,1) forwards",
      fontFamily: "'DM Mono','Fira Code',monospace",
    },
  };

  return (
    <>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@300;400;500&family=Bebas+Neue&display=swap');
        @keyframes jkFadeUp   { from{opacity:0;transform:translateY(16px) scale(0.97)} to{opacity:1;transform:translateY(0) scale(1)} }
        @keyframes jkSlideIn  { from{opacity:0;transform:translateY(8px)} to{opacity:1;transform:translateY(0)} }
        @keyframes jkBlink    { 0%,100%{opacity:1} 50%{opacity:0} }
        @keyframes jkSpin     { from{transform:rotate(0deg)} to{transform:rotate(360deg)} }
        @keyframes jkBounce   { 0%,100%{transform:translateY(0)} 30%{transform:translateY(-14px)} 60%{transform:translateY(-6px)} }
        @keyframes jkPulse    { 0%{box-shadow:0 0 0 0 rgba(200,16,46,0.55)} 70%{box-shadow:0 0 0 12px rgba(200,16,46,0)} 100%{box-shadow:0 0 0 0 rgba(200,16,46,0)} }
        .jk-msg   { animation: jkSlideIn 0.25s ease forwards; }
        .jk-quick:hover { background:rgba(200,16,46,0.18)!important; border-color:#C8102E!important; color:#ff6b6b!important; transform:translateY(-1px); }
        .jk-fab-btn:hover { transform:scale(1.08); box-shadow:0 12px 36px rgba(200,16,46,0.6)!important; }
        .jk-send:hover:not(:disabled) { transform:scale(1.07); box-shadow:0 5px 18px rgba(200,16,46,0.5)!important; }
        .jk-wrap:focus-within { border-color:rgba(200,16,46,0.45)!important; box-shadow:0 0 0 3px rgba(200,16,46,0.1)!important; }
        .jk-msgs::-webkit-scrollbar { width:3px; }
        .jk-msgs::-webkit-scrollbar-thumb { background:rgba(200,16,46,0.3); border-radius:3px; }
        .jk-qbar::-webkit-scrollbar { display:none; }
        @media(max-width:480px){
          .jk-window-mobile { bottom:0!important; right:0!important; width:100vw!important; height:100dvh!important; border-radius:0!important; }
        }
      `}</style>

      {/* ── FAB BUTTON ── */}
      {!open && (
        <button
          className="jk-fab-btn"
          style={S.fab}
          onClick={openChat}
          title="Chat with JK Assistant"
        >
          <JKLogo size={36} />
          {unread > 0 && <span style={S.unread}>{unread}</span>}
        </button>
      )}

      {/* ── CHAT WINDOW ── */}
      {open && (
        <div style={S.window} className="jk-window-mobile">

          {/* Header */}
          <div style={{ padding: "0.85rem 1rem", background: "rgba(15,15,15,0.98)", borderBottom: "1px solid rgba(200,16,46,0.2)", display: "flex", alignItems: "center", justifyContent: "space-between", flexShrink: 0 }}>
            <div style={{ display: "flex", alignItems: "center", gap: "0.65rem" }}>
              <JKLogo size={36} />
              <div>
                <div style={{ fontFamily: "'Bebas Neue',sans-serif", fontSize: "1.1rem", letterSpacing: "0.12em", background: "linear-gradient(135deg,#fff 40%,#C8102E)", WebkitBackgroundClip: "text", WebkitTextFillColor: "transparent", lineHeight: 1.1 }}>
                  JK ASSISTANT
                </div>
                <div style={{ fontSize: "0.56rem", color: "rgba(255,255,255,0.28)", letterSpacing: "0.18em", textTransform: "uppercase", marginTop: "0.1rem" }}>
                  Physio · Gym · Rehab · Diet
                </div>
              </div>
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: "0.5rem" }}>
              <div style={{ display: "flex", alignItems: "center", gap: "0.35rem" }}>
                <div style={{ width: 6, height: 6, borderRadius: "50%", background: apiKey ? "#4ade80" : RED, animation: !apiKey ? "jkPulse 2s infinite" : "none" }} />
                <span style={{ fontSize: "0.58rem", color: "rgba(255,255,255,0.25)", letterSpacing: "0.1em", fontFamily: "'DM Mono',monospace" }}>{apiKey ? "LIVE" : "OFFLINE"}</span>
              </div>
              <button onClick={() => setShowKey(!showKey)} style={{ background: "rgba(255,255,255,0.05)", border: "1px solid rgba(255,255,255,0.1)", borderRadius: 8, width: 30, height: 30, display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", color: "rgba(255,255,255,0.45)", fontSize: "0.85rem" }}>⚙</button>
              <button onClick={closeChat} style={{ background: "rgba(255,255,255,0.05)", border: "1px solid rgba(255,255,255,0.1)", borderRadius: 8, width: 30, height: 30, display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", color: "rgba(255,255,255,0.45)", fontSize: "0.85rem" }}>✕</button>
            </div>
          </div>

          {/* API Key Panel */}
          {showKey && (
            <div style={{ padding: "0.75rem 1rem", background: "rgba(200,16,46,0.05)", borderBottom: "1px solid rgba(200,16,46,0.15)", flexShrink: 0 }}>
              <input
                type="password"
                placeholder="Paste Gemini API key (AIza...)"
                value={apiKey}
                onChange={(e) => setApiKey(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && (setShowKey(false), setError(""))}
                autoFocus
                style={{ width: "100%", background: "rgba(255,255,255,0.05)", border: "1px solid rgba(200,16,46,0.3)", borderRadius: 8, padding: "0.6rem 0.85rem", color: "#e8e8e8", fontFamily: "'DM Mono',monospace", fontSize: "0.78rem", outline: "none", marginBottom: "0.4rem", boxSizing: "border-box" }}
              />
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <span style={{ fontSize: "0.58rem", color: "rgba(255,255,255,0.18)", fontFamily: "'DM Mono',monospace" }}>aistudio.google.com · free key</span>
                <button onClick={() => { setShowKey(false); setError(""); }} style={{ background: `linear-gradient(135deg,${RED},${RED_DARK})`, border: "none", borderRadius: 6, padding: "0.35rem 0.75rem", color: "#fff", fontFamily: "'DM Mono',monospace", fontSize: "0.68rem", cursor: "pointer", fontWeight: 600 }}>
                  Confirm
                </button>
              </div>
            </div>
          )}

          {/* Messages */}
          <div className="jk-msgs" style={{ flex: 1, overflowY: "auto", padding: "1rem", display: "flex", flexDirection: "column", gap: "0.9rem" }}>

            {/* Topic badges */}
            <div style={{ display: "flex", gap: "0.4rem", flexWrap: "wrap", justifyContent: "center", opacity: 0.55 }}>
              {[["🏋️","Gym"],["🦴","Physio"],["🥗","Diet"],["💳","Membership"]].map(([ic, lb]) => (
                <span key={lb} style={{ background: "rgba(200,16,46,0.1)", border: "1px solid rgba(200,16,46,0.22)", borderRadius: 5, padding: "0.18rem 0.5rem", fontSize: "0.58rem", fontFamily: "'DM Mono',monospace", color: "#ff6b6b", letterSpacing: "0.06em", textTransform: "uppercase" }}>
                  {ic} {lb}
                </span>
              ))}
            </div>

            {messages.map((msg, i) => (
              <div key={i} className="jk-msg" style={{ display: "flex", flexDirection: "column", alignItems: msg.role === "user" ? "flex-end" : "flex-start" }}>
                {msg.role === "assistant" && (
                  <div style={{ display: "flex", alignItems: "center", gap: "0.35rem", marginBottom: "0.3rem", fontSize: "0.58rem", color: "rgba(255,255,255,0.22)", letterSpacing: "0.1em", textTransform: "uppercase", fontFamily: "'DM Mono',monospace" }}>
                    <JKLogo size={16} />
                    JK Assistant
                  </div>
                )}
                <div style={{
                  maxWidth: "88%",
                  padding: "0.8rem 1rem",
                  borderRadius: msg.role === "user" ? "16px 16px 4px 16px" : "4px 16px 16px 16px",
                  background: msg.role === "user" ? "linear-gradient(135deg,rgba(200,16,46,0.2),rgba(200,16,46,0.1))" : "rgba(255,255,255,0.04)",
                  border: msg.role === "user" ? "1px solid rgba(200,16,46,0.35)" : "1px solid rgba(255,255,255,0.08)",
                  fontSize: "0.82rem", lineHeight: "1.75",
                  color: msg.role === "user" ? "#ffd0d8" : "rgba(255,255,255,0.75)",
                  fontFamily: "'DM Mono',monospace",
                }}>
                  {msg.role === "assistant" && !msg.done
                    ? <TypewriterText text={msg.text} speed={6} onDone={() => setMessages((prev) => prev.map((m, j) => j === i ? { ...m, done: true } : m))} />
                    : msg.role === "assistant"
                      ? renderMd(msg.text)
                      : <span style={{ whiteSpace: "pre-wrap" }}>{msg.text}</span>
                  }
                </div>
                {msg.role === "user" && (
                  <div style={{ fontSize: "0.56rem", color: "rgba(255,255,255,0.18)", marginTop: "0.2rem", fontFamily: "'DM Mono',monospace" }}>You</div>
                )}
              </div>
            ))}

            {/* Typing indicator */}
            {loading && (
              <div className="jk-msg" style={{ display: "flex", alignItems: "center", gap: "0.5rem" }}>
                <JKLogo size={16} />
                {[0,1,2].map((d) => (
                  <div key={d} style={{ width: 7, height: 7, borderRadius: "50%", background: RED, opacity: 0.7, animation: `jkBlink 1.1s ease-in-out ${d * 0.22}s infinite` }} />
                ))}
                <span style={{ fontSize: "0.6rem", color: "rgba(255,255,255,0.2)", fontFamily: "'DM Mono',monospace" }}>typing...</span>
              </div>
            )}

            {error && (
              <div style={{ padding: "0.6rem 0.85rem", background: "rgba(200,16,46,0.08)", border: "1px solid rgba(200,16,46,0.3)", borderRadius: 8, color: "#ff6b6b", fontSize: "0.72rem", fontFamily: "'DM Mono',monospace" }}>
                ✕ {error}
              </div>
            )}

            <div ref={bottomRef} />
          </div>

          {/* Quick Prompts */}
          <div className="jk-qbar" style={{ display: "flex", gap: "0.4rem", overflowX: "auto", padding: "0.6rem 1rem", borderTop: "1px solid rgba(255,255,255,0.05)", flexShrink: 0 }}>
            {QUICK_PROMPTS.map((q, i) => (
              <button
                key={i}
                className="jk-quick"
                disabled={loading}
                onClick={() => sendMessage(q.label)}
                style={{ background: "rgba(200,16,46,0.07)", border: "1px solid rgba(200,16,46,0.2)", borderRadius: 20, padding: "0.35rem 0.75rem", fontSize: "0.65rem", fontFamily: "'DM Mono',monospace", color: "rgba(255,255,255,0.42)", cursor: "pointer", whiteSpace: "nowrap", transition: "all 0.18s", opacity: loading ? 0.35 : 1 }}
              >
                {q.icon} {q.label}
              </button>
            ))}
          </div>

          {/* Input */}
          <div style={{ padding: "0.75rem", borderTop: "1px solid rgba(200,16,46,0.15)", flexShrink: 0, background: "rgba(10,10,10,0.8)" }}>
            <div className="jk-wrap" style={{ display: "flex", alignItems: "flex-end", gap: "0.6rem", background: "rgba(255,255,255,0.04)", border: "1px solid rgba(255,255,255,0.09)", borderRadius: 12, padding: "0.6rem 0.75rem", transition: "border-color 0.2s, box-shadow 0.2s" }}>
              <textarea
                ref={textareaRef}
                rows={1}
                placeholder="Ask about workouts, physio, diet, membership..."
                value={input}
                onChange={(e) => {
                  setInput(e.target.value);
                  e.target.style.height = "auto";
                  e.target.style.height = Math.min(e.target.scrollHeight, 100) + "px";
                }}
                onKeyDown={(e) => { if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); sendMessage(); } }}
                style={{ flex: 1, background: "transparent", border: "none", outline: "none", color: "#e8e8e8", fontFamily: "'DM Mono',monospace", fontSize: "0.83rem", lineHeight: 1.55, resize: "none", maxHeight: 100 }}
              />
              <button
                className="jk-send"
                disabled={loading || !input.trim()}
                onClick={() => sendMessage()}
                style={{ background: `linear-gradient(135deg,${RED},${RED_DARK})`, border: "none", borderRadius: 8, width: 38, height: 38, flexShrink: 0, cursor: loading || !input.trim() ? "not-allowed" : "pointer", display: "flex", alignItems: "center", justifyContent: "center", transition: "all 0.18s", boxShadow: "0 3px 12px rgba(200,16,46,0.35)", opacity: loading || !input.trim() ? 0.4 : 1 }}
              >
                {loading
                  ? <svg width="15" height="15" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10" stroke="white" strokeWidth="3" fill="none" strokeDasharray="40 20" style={{ animation: "jkSpin 0.9s linear infinite" }} /></svg>
                  : <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="22" y1="2" x2="11" y2="13" /><polygon points="22 2 15 22 11 13 2 9 22 2" /></svg>
                }
              </button>
            </div>
          </div>

          {/* Footer */}
          <div style={{ textAlign: "center", padding: "0.35rem", fontSize: "0.55rem", color: "rgba(255,255,255,0.1)", letterSpacing: "0.12em", textTransform: "uppercase", fontFamily: "'DM Mono',monospace", borderTop: "1px solid rgba(200,16,46,0.08)" }}>
            JK Physio / Gym / Rehab · Powered by Gemini AI
          </div>
        </div>
      )}
    </>
  );
}
